window.AnalyticsHub = (() => {
  let host;
  let exportSnapshot=null;
  const ui={tab:new URLSearchParams(location.search).get('view')==='performance'?'performance':window.ProblemInsights?'problems':'overview',channel:'all',point:6,chart:'volume',table:false,definitions:false};
  const dataset=()=>window.HubAnalyticsData.snapshot(host.getState().metricsPeriod,ui.channel);
  const escape=value=>host.escape(value);
  const number=value=>Number(value).toLocaleString('en-US');
  const percent=value=>value===null?'—':value.toFixed(1)+'%';
  const seconds=value=>value===null?'—':(value/1000).toFixed(1)+'s';
  const icon=(name)=>host.icon(name,'small');
  const action=(text,name,extra='',tone='')=>host.button(text,'analytics-'+name,tone,extra);
  const tag=(text,tone='')=>host.badge(text,tone);
  const scopeNote='固定模拟样本；与下方本地工作区待办分开统计。';
  const definitions=[['有效服务问题','按服务诉求去重，排除测试、垃圾与历史存档。样本中每条记录代表一个独立问题。'],['确认解决率','已获得解决证据的问题 / 同期有效服务问题。AI 独立解决与人工协同解决互斥；两者相加为确认解决。关闭会话、创建工单和客户不再回复，不算解决。'],['AI 独立解决率','未进入人工处理且有解决证据的问题 / 同期全部有效服务问题。不应为了指标阻止人工接管。'],['人工复核正确率','人工判为正确的适用答案 / 已复核适用答案。本演示每个被抽检的问题取一条适用答案，展示实际分子、分母及 95% Wilson 区间，不以模型自评替代。'],['首条实质回复','从进线到第一条提供实际帮助的回复。排除“已收到”等占位内容，P50 / P95 按同一筛选下的样本计算。'],['比较周期','7 天样本对比前一周相同天数；单日样本对比前一周同一天。比率比较使用百分点，数量使用相对变化；基线为 0 时不显示增幅。']];

  function refresh(focusId){
    const container=document.getElementById('main-content');
    const scroll=container?.scrollTop||0;
    host.render();
    const fresh=document.getElementById('main-content');
    if(fresh)fresh.scrollTop=scroll;
    if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
  }

  function delta(current,previous,ratio=false){
    if(current===null||previous===null||(!ratio&&!previous))return '<span class="dash-delta muted">无可比基线</span>';
    const difference=ratio?current-previous:(current-previous)/previous*100;
    const rounded=Math.abs(difference)<.05?0:difference;
    return `<span class="dash-delta ${rounded>0?'positive':rounded<0?'negative':'neutral'}">${icon(rounded>0?'arrow-up-right':rounded<0?'arrow-down':'arrow-right')}${rounded>0?'+':''}${rounded.toFixed(1)}${ratio?' 个百分点':'%'}</span>`;
  }

  function metricStrip(snapshot){
    const total=snapshot.total;
    const previous=snapshot.previous;
    const metrics=[{name:'有效服务问题',value:number(total.cases),unit:'件',delta:delta(total.cases,previous.cases),note:'已去重 · 不含历史存档'}, {name:'确认解决率',value:total.solveRate===null?'—':total.solveRate.toFixed(1),unit:'%',delta:delta(total.solveRate,previous.solveRate,true),note:`${number(total.solved)} / ${number(total.cases)} 个问题有解决证据`}, {name:'AI 独立解决率',value:total.aiRate===null?'—':total.aiRate.toFixed(1),unit:'%',delta:delta(total.aiRate,previous.aiRate,true),note:`${number(total.ai)} / ${number(total.cases)} 个问题未转人工`}, {name:'人工复核正确率',value:total.accuracy===null?'—':total.accuracy.toFixed(1),unit:'%',delta:delta(total.accuracy,previous.accuracy,true),note:`${number(total.correct)} / ${number(total.reviewed)} 条适用答案`}];
    return `<section class="metrics-grid dash-metrics" aria-label="当前筛选核心指标">${metrics.map((metric,index)=>`<article class="dash-metric"><div class="dash-metric-name"><span>${metric.name}</span>${host.button(icon('info-circle'),'metric-definition','icon-button',`data-name="${metric.name}" aria-label="${metric.name}口径"`)}</div><div class="dash-value">${metric.value}<small>${metric.value==='—'?'':metric.unit}</small></div><p>${metric.note}</p><div class="dash-comparison">${metric.delta}<span>较对比期</span></div>${index===3&&snapshot.interval?`<span class="dash-confidence">95% 区间 ${snapshot.interval.map(value=>value.toFixed(1)+'%').join('–')}</span>`:''}</article>`).join('')}</section>`;
  }

  function panelHead(title,description,controls=''){
    return `<div class="dash-panel-head"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${controls}</div>`;
  }

  function trendPanel(snapshot){
    const trend=snapshot.trend;
    const selected=Math.min(ui.point,trend.length-1);
    const active=trend[selected];
    const rateMode=ui.chart==='rate';
    const ceiling=rateMode?100:Math.max(40,Math.ceil(Math.max(...trend.map(entry=>entry.cases))/40)*40);
    const positionX=index=>72+index*90;
    const positionY=value=>204-value/ceiling*166;
    const series=rateMode?[{key:'solveRate',label:'确认解决率',color:'forest'},{key:'aiRate',label:'AI 独立解决率',color:'clay'}]:[{key:'cases',label:'有效问题',color:'forest'},{key:'solved',label:'确认解决',color:'clay'}];
    const valid=series.filter(item=>trend.every(entry=>entry[item.key]!==null));
    const chart=`<svg viewBox="0 0 666 250" class="dash-trend-svg" aria-hidden="true" focusable="false">${Array.from({length:5},(_,index)=>{const value=ceiling/4*index;const vertical=positionY(value);return `<line x1="65" x2="635" y1="${vertical.toFixed(2)}" y2="${vertical.toFixed(2)}" class="dash-grid-line"/><text class="dash-axis-label" x="50" y="${(vertical+4).toFixed(2)}" text-anchor="end">${rateMode?value+'%':Number(value.toFixed(1))}</text>`;}).join('')}${valid.map((item,index)=>{const points=trend.map((entry,point)=>`${positionX(point).toFixed(2)},${positionY(entry[item.key]).toFixed(2)}`).join(' ');return `${index===0?`<polygon points="72.00,204.00 ${points} 612.00,204.00" class="dash-chart-fill"/>`:''}<polyline points="${points}" class="dash-chart-line ${item.color}"/>${trend.map((entry,point)=>`<circle cx="${positionX(point).toFixed(2)}" cy="${positionY(entry[item.key]).toFixed(2)}" r="${point===selected?'4.5':'3'}" class="dash-chart-point ${item.color}"/>`).join('')}`;}).join('')}<line x1="${positionX(selected).toFixed(2)}" x2="${positionX(selected).toFixed(2)}" y1="28" y2="209" class="dash-active-line"/>${trend.map((entry,index)=>`<text class="dash-time-label" x="${positionX(index).toFixed(2)}" y="236" text-anchor="middle">${entry.label}</text>`).join('')}</svg>`;
    const pointText=entry=>`${entry.label}，有效问题 ${entry.cases}，确认解决 ${entry.solved}，解决率 ${percent(entry.solveRate)}`;
    return `<section class="dash-panel dash-trend">${panelHead('服务趋势','按进线时间分组 · 解决结果截至样本快照',`<div class="dash-toggle" aria-label="趋势类型">${[['volume','问题量'],['rate','解决率']].map(([key,label])=>action(label,'chart',`id="dash-chart-${key}" data-value="${key}" aria-pressed="${ui.chart===key}"`,ui.chart===key?'selected':'')).join('')}</div>`)}<div class="dash-chart-legend">${series.map(item=>`<span><i class="${item.color}"></i>${item.label}</span>`).join('')}<span class="dash-chart-unit">${rateMode?'单位：%':'单位：件'}</span></div><div class="dash-chart-stage">${chart}<div class="dash-chart-hitarea">${trend.map((entry,index)=>`<button id="dash-point-${index}" class="dash-chart-hit ${index===selected?'selected':''}" data-action="analytics-point" data-value="${index}" aria-pressed="${index===selected}" aria-label="${pointText(entry)}" title="${pointText(entry)}"><span class="sr-only">${entry.label}</span></button>`).join('')}</div></div><div class="dash-point-summary" aria-live="polite"><strong>${active.label}</strong><span>有效问题 <b>${active.cases}</b></span><span>确认解决 <b>${active.solved}</b></span><span>解决率 <b>${percent(active.solveRate)}</b></span>${action(icon('list-check')+' 数据','table','id="dash-data-toggle" aria-expanded="'+ui.table+'"','quiet small')}</div>${ui.table?`<div class="dash-table-scroll dash-daily-table"><table><caption class="sr-only">${snapshot.label}逐时或逐日样本明细</caption><thead><tr><th>时间</th><th>有效问题</th><th>确认解决</th><th>AI 独立</th><th>人工复核</th></tr></thead><tbody>${trend.map(entry=>`<tr><th scope="row">${entry.label}</th><td>${entry.cases}</td><td>${entry.solved}</td><td>${entry.ai}</td><td>${entry.correct} / ${entry.reviewed}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;
  }

  function outcomesPanel(snapshot){
    const total=snapshot.total;
    const entries=[{name:'AI 独立解决',key:'ai',tone:'forest'},{name:'人工协同解决',key:'assisted',tone:'clay'},{name:'已知未解决',key:'open',tone:'sand'},{name:'结果待确认',key:'unknown',tone:'stone'}];
    let consumed=0;
    const gradient=entries.map(entry=>{const start=consumed;consumed+=total.cases?total[entry.key]/total.cases*100:0;return `var(--dash-${entry.tone}) ${start.toFixed(4)}% ${consumed.toFixed(4)}%`;}).join(',');
    return `<section class="dash-panel dash-outcomes">${panelHead('问题解决情况','同一进线样本的互斥结果分布')}<div class="dash-outcome-content"><div class="dash-donut" style="--segments:conic-gradient(${gradient})" role="img" aria-label="${entries.map(entry=>entry.name+total[entry.key]+'件').join('，')}"><div><strong>${number(total.solved)}</strong><span>已确认解决</span></div></div><ul class="dash-outcome-legend">${entries.map(entry=>`<li><span><i class="${entry.tone}"></i>${entry.name}</span><strong>${number(total[entry.key])}</strong><small>${percent(window.HubAnalyticsData.rate(total[entry.key],total.cases))}</small></li>`).join('')}</ul></div><div class="dash-panel-note">${icon('info-circle')}<span>客户没有继续回复，不代表问题已解决。</span></div></section>`;
  }

  function channelsPanel(snapshot){
    const max=Math.max(...snapshot.channels.map(entry=>entry.cases),1);
    return `<section class="dash-panel dash-channel-panel">${panelHead('渠道表现','比较同一范围的服务量、结果与首响',ui.channel==='all'?tag('3 个实时入口'):action('返回全部渠道','channel','data-value="all"','quiet small'))}<div class="dash-table-scroll"><table class="dash-channel-table"><caption class="sr-only">渠道表现，点击渠道筛选全部固定样本指标</caption><thead><tr><th>服务入口</th><th>有效问题</th><th>确认解决率</th><th>AI 独立解决率</th><th>首响 P50</th><th>人工复核</th></tr></thead><tbody>${snapshot.channels.map(channel=>`<tr><th scope="row"><button class="dash-channel-name" data-action="analytics-channel" data-value="${channel.id}" aria-label="筛选${channel.name}">${host.channelMark(channel.id)}<span>${channel.name}</span>${icon('chevron-right')}</button></th><td><div class="dash-volume"><b>${channel.cases}</b><span><i style="width:${channel.cases/max*100}%"></i></span></div></td><td>${percent(channel.solveRate)}</td><td>${percent(channel.aiRate)}</td><td>${seconds(channel.p50)}</td><td><strong>${percent(channel.accuracy)}</strong><small>${channel.correct} / ${channel.reviewed} 条</small></td></tr>`).join('')}</tbody></table></div><div class="dash-panel-note dash-channel-note"><span>点击渠道名称，可联动筛选大盘。</span><span>当前范围首响 <b>P50 ${seconds(snapshot.total.p50)}</b> / <b>P95 ${seconds(snapshot.total.p95)}</b></span></div></section>`;
  }

  function topicsPanel(snapshot){
    const max=Math.max(...snapshot.categories.map(entry=>entry.cases),1);
    return `<section class="dash-panel dash-topics">${panelHead('客户在问什么','当前筛选 · 按问题量排序')}<div class="dash-topic-list">${snapshot.categories.map((entry,index)=>`<div class="dash-topic"><span class="dash-rank">${String(index+1).padStart(2,'0')}</span><div><span>${entry.name}</span><span class="dash-topic-track"><i style="width:${entry.cases/max*100}%"></i></span></div><strong>${entry.cases}<small>件</small></strong><span>${percent(entry.solveRate)}<small>确认解决</small></span></div>`).join('')}</div></section>`;
  }

  function localActions(){
    const state=host.getState();
    const review=state.reviews.filter(entry=>entry.status==='待复核');
    const handoff=state.cases.filter(entry=>entry.status==='待人工接管'&&entry.owner!=='readonly');
    const knowledge=state.knowledge.filter(entry=>entry.status==='待审核');
    const badcases=state.trace.badcases.filter(entry=>entry.status!=='已关闭');
    const rows=[{name:'回复待复核',count:review.length,hint:'核实承诺与知识适用范围',action:'quality'}, {name:'客户等待接管',count:handoff.length,hint:'先接待明确要求人工的客户',action:'handoff'}, {name:'知识草稿待审核',count:knowledge.length,hint:'审核前不用于自动回复',action:'knowledge'}, {name:'问题案例待跟进',count:badcases.length,hint:'补齐归因、修正与回归记录',action:'badcases'}];
    return `<section class="dash-panel dash-attention">${panelHead('需要你跟进','本地工作区 · 不受上方日期 / 渠道筛选影响',tag('当前待办'))}<div class="dash-attention-list">${rows.map(entry=>`<button data-action="analytics-work" data-value="${entry.action}" class="dash-action-row"><span class="dash-action-count ${entry.count?'has-items':''}">${entry.count}</span><span><strong>${entry.name}</strong><small>${entry.hint}</small></span>${icon('arrow-up-right')}</button>`).join('')}</div><p class="dash-local-note">处理后回到大盘，待办数量会同步变化；历史样本指标不变。</p></section>`;
  }

  function qualityPage(snapshot){
    const total=snapshot.total;
    const trace=host.getState().trace;
    const stages=[['问题案例',trace.badcases.length,'badcases'],['回归样本',trace.samples.length,'datasets'],['评测记录',trace.runs.length,'releases'],['发布记录',trace.releases.length,'releases']];
    return `<div class="dash-quality-layout"><section class="dash-panel">${panelHead('抽检结果','固定模拟样本 · 只计算人工标注的适用答案',tag('人工复核'))}<div class="dash-review-overview"><div><strong>${percent(total.accuracy)}</strong><p>${total.correct} / ${total.reviewed} 条判为正确</p><span>${snapshot.interval?'95% Wilson 区间 '+snapshot.interval.map(value=>value.toFixed(1)+'%').join(' — '):'暂无可计算的复核样本'}</span></div><div class="dash-review-split"><span><i class="forest"></i>正确 <b>${total.correct}</b></span><span><i class="clay"></i>需修正 <b>${total.incorrect}</b></span><span><i class="stone"></i>未抽检 <b>${total.cases-total.reviewed}</b></span></div></div><div class="dash-error-list">${snapshot.errors.map(entry=>`<div><span>${entry.name}</span><span class="dash-error-track"><i style="width:${total.incorrect?entry.count/total.incorrect*100:0}%"></i></span><b>${entry.count}</b></div>`).join('')}</div><p class="dash-panel-note">每条错误样本归入一个主要原因。未抽检、满意度、模型自评不计入正确率。</p></section><section class="dash-panel dash-loop">${panelHead('问题回流进度','本地工作区 · 实际演示记录，不是历史样本漏斗')}<div class="dash-stage-counts">${stages.map(([name,count,tab])=>`<button data-action="trace-tab" data-value="${tab}"><strong>${count}</strong><span>${name}</span>${icon('arrow-up-right')}</button>`).join('')}</div><div class="dash-loop-records">${trace.badcases.slice(0,3).map(entry=>`<button data-action="trace-bad-open" data-id="${escape(entry.id)}"><div><strong>${escape(entry.title)}</strong><span>${escape(entry.id)} · ${escape(entry.owner)}</span></div>${tag(entry.status,'amber')}${icon('chevron-right')}</button>`).join('')||'<p class="dash-empty-copy">还没有问题案例。可从质检记录或 Trace 登记。</p>'}</div><p class="dash-panel-note">回归通过不等于业务正确；样本需人工确认，发布需单独审核，不自动训练。</p></section></div>${channelsPanel(snapshot)}`;
  }

  function agentsPage(){
    const engine=window.ManagerHub.getEngine();
    const tasks=engine.get().tasks;
    const steps=tasks.flatMap(task=>task.steps);
    const metrics=[['任务总数',tasks.length,'包含预置、执行与历史任务'],['执行中',tasks.filter(task=>['执行中','排队中'].includes(task.status)).length,'运行与排队分别保留'],['待确认',tasks.filter(task=>task.status==='待确认').length,'准备完成，未自动发送'],['失败任务',tasks.filter(task=>task.status==='失败').length,'可查看步骤并重试']];
    return `<section class="dash-local-banner">${icon('terminal-2')}<span>本地调度记录 · 未连接真实模型与外部 Agent；不套用上方历史样本的统计口径。</span>${action('刷新记录','refresh','id="dash-refresh"','quiet small')}</section><div class="dash-local-metrics">${metrics.map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div><section class="dash-panel">${panelHead('助手分工与负载','按当前本地执行步骤统计，空闲不代表业务停用',host.button('进入项目助手 '+icon('arrow-up-right'),'navigate','quiet small','data-page="manager"'))}<div class="dash-agent-grid">${engine.stats().map(worker=>{const entries=steps.filter(step=>step.worker===worker.id);const completed=entries.filter(step=>step.status==='已完成').length;const failed=entries.filter(step=>step.status==='失败').length;return `<article class="dash-worker"><div class="dash-worker-top">${window.HubIdentity.worker(worker.id,'md')}<div><h3>${escape(worker.name)}</h3><span>${worker.id==='expert'?'外部协作 · 模拟端点':'当前任务容量 1 步'}</span></div>${tag(!worker.enabled?'已暂停':worker.running.length?'执行中':'空闲',worker.running.length?'green':'')}</div><div class="dash-worker-counts"><span>运行 <b>${worker.running.length}</b></span><span>排队 <b>${worker.waiting.length}</b></span><span>完成 <b>${completed}</b></span><span>失败 <b>${failed}</b></span></div><div class="dash-worker-load" role="img" aria-label="正在执行 ${worker.running.length} 步，容量 1 步"><i style="width:${worker.running.length*100}%"></i></div></article>`;}).join('')}</div></section><section class="dash-panel dash-task-panel">${panelHead('最近任务','点击任务查看分工、工具返回和 Trace',host.button('全部执行记录 '+icon('arrow-up-right'),'trace-tab','quiet small','data-value="traces"'))}<div class="dash-table-scroll"><table><thead><tr><th>任务</th><th>关联客户</th><th>进度</th><th>状态</th><th>操作</th></tr></thead><tbody>${tasks.slice(0,8).map(task=>`<tr><th scope="row"><strong>${escape(task.id)}</strong><small>${escape(engine.kinds[task.kind])}</small></th><td>${escape(task.snapshot.item.name)}<small>${escape(task.caseId)}</small></td><td>${task.steps.filter(step=>step.status==='已完成').length} / ${task.steps.length} 步</td><td>${tag(task.status,/失败/.test(task.status)?'red':/待|排队/.test(task.status)?'amber':'')}</td><td><button class="text-button" data-action="analytics-task" data-id="${escape(task.id)}">查看任务 ${icon('chevron-right')}</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="dash-empty-copy">还没有任务。给项目助手交代一件事后，这里会留下记录。</div></td></tr>'}</tbody></table></div></section>`;
  }

  function empty(){
    return `<section class="dash-empty">${icon('archive')}<h2>历史存档不计入实时服务指标</h2><p>存档可以用于参考，但无法据此确认首响时间和实际解决结果。</p>${action('查看全部实时渠道','channel','data-value="all"','primary')}</section>`;
  }

  function page(){
    if(ui.tab==='performance')return window.PerformanceHub.page();
    if(ui.tab==='problems'&&window.ProblemInsights)return window.ProblemInsights.page();
    const snapshot=dataset();
    const local=ui.tab==='agents';
    return `<div class="dash-page"><header class="dash-header"><div><div class="dash-eyebrow"><span></span>服务统计</div><h1>运营大盘</h1><p>查看服务结果、渠道表现和处理效率。</p></div><div class="dash-header-actions">${action(icon('adjustments-horizontal')+' 指标口径','definitions','id="dash-definitions-toggle" aria-expanded="'+ui.definitions+'"','quiet')}${!local?host.button(icon('download')+' 导出报表','export-metrics','', 'id="dash-export"'):host.button('项目助手 '+icon('arrow-up-right'),'navigate','','data-page="manager"')}</div></header><div class="dash-navigation"><nav aria-label="运营视图">${[...(window.ProblemInsights?[['problems','问题洞察']]:[]),['overview','服务概览'],['performance','性能与 SLA'],['quality','质量与回流'],['agents','助手协同']].map(([key,name])=>action(name,'tab',`id="dash-tab-${key}" data-value="${key}" aria-pressed="${ui.tab===key}"`,ui.tab===key?'selected':'')).join('')}</nav><span>${local?'本地工作区 · 手动刷新':'样本快照 · 2026.11.07 20:00'}</span></div>${!local?`<section class="dash-filterbar" aria-label="固定模拟样本筛选"><div class="dash-filter-fields"><label>${icon('calendar')}<select id="metrics-period" aria-label="统计周期"><option value="week" ${snapshot.period==='week'?'selected':''}>7 天样本 · 11.01—11.07</option><option value="today" ${snapshot.period==='today'?'selected':''}>单日样本 · 11.07</option></select></label><label>${icon('filter')}<select id="analytics-channel" aria-label="大盘渠道筛选">${[{id:'all',name:'全部实时渠道'},...window.HubAnalyticsData.channels,{id:'archive',name:'历史存档（不计入）'}].map(channel=>`<option value="${channel.id}" ${ui.channel===channel.id?'selected':''}>${channel.name}</option>`).join('')}</select></label></div><span>对比 ${snapshot.comparisonLabel}</span><span class="dash-sample-label">${icon('database')}固定模拟样本</span></section>`:''}${ui.definitions?`<section class="dash-definitions" aria-label="指标口径说明"><div><h2>指标口径</h2>${action(icon('x'),'definitions','aria-label="收起指标口径"','icon-button')}</div><dl>${definitions.map(([title,text])=>`<div><dt>${title}</dt><dd>${text}</dd></div>`).join('')}</dl></section>`:''}${local?agentsPage():`${metricStrip(snapshot)}${!snapshot.total.cases?empty()+(ui.tab==='overview'?localActions():''):ui.tab==='quality'?qualityPage(snapshot):`<div class="dash-primary-grid">${trendPanel(snapshot)}${outcomesPanel(snapshot)}</div>${channelsPanel(snapshot)}<div class="dash-secondary-grid">${topicsPanel(snapshot)}${localActions()}</div>`}${ui.tab==='quality'?localActions():''}`}<footer class="dash-footer"><span>${icon('shield-lock')}${local?'记录仅来自本地演示，不代表真实模型执行。':scopeNote}</span><span>${local?'最多同时处理 2 个任务':'口径版本 OP-01 · 历史快照非今日实时业绩'}</span></footer></div>`;
  }

  function csv(snapshot){
    const total=snapshot.total;
    const rows=[['连山 · 模拟运营报表'],['数据性质','固定模拟样本，非客户真实业绩'],['日期范围',snapshot.label],['渠道',snapshot.channelLabel],['对比期',snapshot.comparisonLabel],['快照截止','2026-11-07 20:00'],[],['指标','分子/数量','分母','比率'],['有效服务问题',total.cases,'',''],['确认解决率',total.solved,total.cases,percent(total.solveRate)],['AI 独立解决率',total.ai,total.cases,percent(total.aiRate)],['人工复核正确率',total.correct,total.reviewed,percent(total.accuracy)],['首条实质回复 P50(ms)',total.p50??'','',''],['首条实质回复 P95(ms)',total.p95??'','',''],['95% Wilson 区间',snapshot.interval?snapshot.interval.map(value=>value.toFixed(1)+'%').join(' — '):'无样本'],[],['时间','有效问题','确认解决','AI 独立解决','正确答案','复核答案'],...snapshot.trend.map(entry=>[entry.key,entry.cases,entry.solved,entry.ai,entry.correct,entry.reviewed]),[],['渠道','有效问题','确认解决','AI 独立解决','正确答案','复核答案','首响P50(ms)'],...snapshot.channels.map(entry=>[entry.name,entry.cases,entry.solved,entry.ai,entry.correct,entry.reviewed,entry.p50??'']),[],['结果分布','件数'],...['ai','assisted','open','unknown'].map((key,index)=>[['AI 独立解决','人工协同解决','已知未解决','结果待确认'][index],total[key]]),[],['咨询分类','件数','确认解决'],...snapshot.categories.map(entry=>[entry.name,entry.cases,entry.solved]),[],['复核主要错误','条数'],...snapshot.errors.map(entry=>[entry.name,entry.count]),[],['对比期指标','有效问题','确认解决','AI独立解决','事实正确','复核样本'],[snapshot.comparisonLabel,snapshot.previous.cases,snapshot.previous.solved,snapshot.previous.ai,snapshot.previous.correct,snapshot.previous.reviewed]];
    return '\ufeff'+rows.map(row=>row.map(value=>{const text=String(value??'');return '"'+(/^[=+@-]/.test(text)?"'":'')+text.replaceAll('"','""')+'"';}).join(',')).join('\r\n');
  }

  function openExport(){
    exportSnapshot=dataset();
    if(!exportSnapshot.total.cases){host.toast('当前范围没有可导出的实时服务样本。',true);return;}
    host.showDialog('导出当前筛选的报表','只下载固定模拟样本的聚合数据，不包含客户聊天或本地待办。',`<dl class="dash-export-meta"><div><dt>日期</dt><dd>${exportSnapshot.label}</dd></div><div><dt>渠道</dt><dd>${exportSnapshot.channelLabel}</dd></div><div><dt>有效问题</dt><dd>${exportSnapshot.total.cases} 件</dd></div></dl><p class="dash-export-note">包含指标分子 / 分母、时间明细、渠道、问题分类与结果分布。文件标注“固定模拟样本”。</p><label class="dash-export-consent"><input id="analytics-export-consent" type="checkbox">我确认下载的是模拟报表，不作为实际经营数据使用。</label>`,host.footer('确认下载 CSV','analytics-export-confirm'),'compact');
  }

  function dispatch(name,element){
    if(name.startsWith('perf-'))return window.PerformanceHub.dispatch(name.slice(5),element);
    const value=element.dataset.value;
    if(name==='tab'&&['overview','performance','quality','agents',...(window.ProblemInsights?['problems']:[])].includes(value)){ui.tab=value;refresh('dash-tab-'+value);}
    else if(name==='channel'){ui.channel=[...window.HubAnalyticsData.channels.map(entry=>entry.id),'all','archive'].includes(value)?value:'all';ui.point=6;refresh('analytics-channel');}
    else if(name==='chart'&&['volume','rate'].includes(value)){ui.chart=value;refresh('dash-chart-'+value);}
    else if(name==='point'){const index=Number(value);if(Number.isInteger(index)&&index>=0&&index<7){ui.point=index;refresh('dash-point-'+index);}}
    else if(name==='table'){ui.table=!ui.table;refresh('dash-data-toggle');}
    else if(name==='definitions'){ui.definitions=!ui.definitions;refresh('dash-definitions-toggle');}
    else if(name==='refresh')refresh('dash-refresh');
    else if(name==='task'){host.navigate('manager');window.ManagerHub.dispatch('open',{dataset:{id:element.dataset.id}});}
    else if(name==='work'){
      if(value==='badcases')window.TraceHub.dispatch('tab',{dataset:{value:'badcases'}});
      else if(value==='handoff'){const item=host.getState().cases.find(entry=>entry.status==='待人工接管'&&entry.owner!=='readonly');if(item){host.getView().caseId=item.id;host.getView().queue='all';host.getView().channel='all';host.getView().search='';host.getView().mobileCase=true;}host.navigate('workspace');}
      else if(value==='quality'||value==='knowledge'){host.navigate(value);host.getView().filter=value==='quality'?'待复核':'待审核';host.render();}
    }
    else if(name==='export-confirm'){
      if(!document.getElementById('analytics-export-consent')?.checked)return host.toast('请先确认报表的数据范围。',true);
      if(!exportSnapshot)return host.toast('导出范围已失效，请重新打开导出。',true);
      try{const snapshot=exportSnapshot;const blob=new Blob([csv(snapshot)],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`连山_模拟报表_${snapshot.period}_${snapshot.channel}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exportSnapshot=null;host.closeDialog();host.toast('已下载当前筛选的模拟报表。');}catch{host.toast('当前浏览器无法下载文件，请在浏览器中重新打开此演示。',true);}
    }
  }

  function change(identifier,value){
    if(identifier==='metrics-period'){host.getState().metricsPeriod=value==='today'?'today':'week';ui.point=6;host.persist();refresh('metrics-period');}
    if(identifier==='analytics-channel')dispatch('channel',{dataset:{value}});
  }

  return {configure(adapter){host=adapter;window.ProblemInsights?.configure(adapter);window.PerformanceHub.configure(adapter);},page,dispatch,change,openView(tab,scope={}){if(!['problems','overview','performance','quality','agents'].includes(tab))return;ui.tab=tab;if(scope.channel)ui.channel=scope.channel;if(scope.period)host.getState().metricsPeriod=scope.period;host.persist();host.navigate('analytics');},openExport,snapshot:dataset,csv,reset(){Object.assign(ui,{tab:window.ProblemInsights?'problems':'overview',channel:'all',point:6,chart:'volume',table:false,definitions:false});window.ProblemInsights?.reset();window.PerformanceHub.reset();exportSnapshot=null;}};
})();

window.PerformanceHub = (() => {
  let host;
  const initial=()=>({period:'week',channel:'all',agent:'all',model:'all',metric:'ttftMs',status:'slow',range:null,day:null,limit:12,detail:null,definitions:false});
  let ui=initial();let exportSnapshot;
  const data=()=>window.HubPerformanceData;
  const escape=value=>host.escape(String(value??''));
  const button=(text,action,extra='',tone='')=>host.button(text,'analytics-perf-'+action,tone,extra);
  const rate=(count,total)=>data().rate(count,total);
  const pct=value=>value===null?'—':value.toFixed(1)+'%';
  const elapsed=value=>value===null||!Number.isFinite(value)?'—':value>=60000?(value/60000).toFixed(1)+' min':value<1000?Math.round(value)+' ms':(value/1000).toFixed(2)+' s';
  const labels={success:'成功',timeout:'超时',error:'失败',cancelled:'已取消',running:'处理中'};
  const tone=status=>status==='success'?'green':['error','timeout'].includes(status)?'red':'amber';
  const agentName=identifier=>data().agents.find(agent=>agent.id===identifier)?.name||identifier;
  const modelName=identifier=>data().models.find(model=>model.id===identifier)?.name||identifier;
  const channelName=identifier=>window.HubAnalyticsData.channels.find(channel=>channel.id===identifier)?.name||'全部渠道';
  const targetLimits={ttftMs:[100,120000],endToEndMs:[100,300000],aiFrtMs:[100,300000],humanFrtMs:[1000,3600000],goal:[1,100]};
  function targets(){const stored=host.getState().performanceTargets||{};return Object.fromEntries(Object.entries(data().defaults).map(([key,value])=>[key,Number.isFinite(stored[key])&&stored[key]>=targetLimits[key][0]&&stored[key]<=targetLimits[key][1]?stored[key]:value]));}
  const snapshot=()=>data().snapshot(ui,targets());
  function refresh(identifier,top=false){const main=document.getElementById('main-content');const scroll=top?0:main?.scrollTop||0;host.render();const fresh=document.getElementById('main-content');if(fresh)fresh.scrollTop=scroll;if(identifier)document.getElementById(identifier)?.focus({preventScroll:true});}
  const sectionHead=(title,note,controls='')=>`<div class="dash-panel-head"><div><h2>${title}</h2><p>${note}</p></div>${controls}</div>`;
  function navigation(){return `<div class="dash-navigation"><nav aria-label="运营视图">${[['problems','问题洞察'],['overview','服务概览'],['performance','性能与 SLA'],['quality','质量与回流'],['agents','助手协同']].map(([key,name])=>host.button(name,'analytics-tab',key==='performance'?'selected':'',`id="dash-tab-${key}" data-value="${key}" aria-pressed="${key==='performance'}"`)).join('')}</nav><span>预置遥测 · 非实时监控</span></div>`;}
  function filter(identifier,label,options){return `<label><span>${label}</span><select id="perf-${identifier}" aria-label="${label}">${options.map(([key,title])=>`<option value="${key}" ${ui[identifier]===key?'selected':''}>${title}</option>`).join('')}</select></label>`;}
  function filters(){return `<section class="perf-filters" aria-label="性能样本筛选">${filter('period','统计周期',[['week','11.01—11.07 · 7 天'],['today','11.07 · 单日']])}${filter('channel','来源渠道',[['all','全部渠道'],...window.HubAnalyticsData.channels.map(item=>[item.id,item.name]),['archive','历史存档（不计入）']])}${filter('agent','业务助手',[['all','全部助手'],...data().agents.map(item=>[item.id,item.name])])}${filter('model','模型版本',[['all','全部模型'],...data().models.map(item=>[item.id,item.name])])}<span class="perf-data-source">固定模拟样本<br>截至 2026.11.07 23:59</span></section>`;}
  function headline(report){
    const total=report.total;const target=targets();const metrics=total.metrics;
    const items=[['端到端目标达标',pct(total.sloRate),`${total.sloMet} / ${total.terminal} 个有效终态请求`,`${elapsed(target.endToEndMs)} 内交付 · 目标 ${target.goal}%`,total.sloRate!==null&&total.sloRate<target.goal],['首 token · P95',elapsed(metrics.ttftMs.p95),`已返回首 token · n=${metrics.ttftMs.n}`,`P50 ${elapsed(metrics.ttftMs.p50)} · P99 ${elapsed(metrics.ttftMs.p99)}`,metrics.ttftMs.p95!==null&&metrics.ttftMs.p95>target.ttftMs],['端到端 · P95',elapsed(metrics.endToEndMs.p95),`仅成功请求 · n=${metrics.endToEndMs.n}`,`P50 ${elapsed(metrics.endToEndMs.p50)} · P99 ${elapsed(metrics.endToEndMs.p99)}`,metrics.endToEndMs.p95!==null&&metrics.endToEndMs.p95>target.endToEndMs],['调度排队 · P95',elapsed(metrics.queueMs.p95),`已出队请求 · n=${metrics.queueMs.n}`,`${total.running} 个处理中 · 单列保留`,false],['请求超时率',pct(total.timeoutRate),`${total.timeout} / ${total.terminal} 个有效终态请求`,'超时请求计入目标未达标',total.timeout>0],['请求成功率',pct(total.successRate),`${total.success} / ${total.terminal} 个有效终态请求`,`${total.errors} 失败 · ${total.cancelled} 取消 · ${total.running} 处理中`,false]];
    return `<section class="perf-headline" aria-label="性能核心指标">${items.map(([title,value,note,detail,alert])=>`<article class="${alert?'is-alert':''}"><span>${title}</span><strong>${value}</strong><p>${note}</p><small>${detail}</small></article>`).join('')}</section><div class="perf-scope-note"><span>有效终态 = 成功 + 超时 + 失败；取消与处理中单列，不静默丢弃。当前 ${total.count} 个请求。</span>${button('查看统计口径','definitions','aria-expanded="'+ui.definitions+'"','quiet small')}</div>`;
  }
  function definitions(){return `<section class="dash-definitions"><div><h2>口径与采集边界</h2></div><dl><div><dt>P50 / P95 / P99</dt><dd>按当前范围逐条样本升序排列，取 ceil(n × p) 对应值。分位数不相加，也不对各组 P95 求平均；无样本显示 —，n &lt; 100 的 P99 只供观察。</dd></div><div><dt>失败与未完成</dt><dd>端到端延迟只用成功请求，失败和超时始终留在有效终态分母及未达标数中。取消、处理中单列；阶段耗时只取已有结束事件，排队中的值为等待下限。</dd></div><div><dt>客户首响与模型首 token 不同</dt><dd>客户首响从客户消息进入渠道算起，到首条实质回复被渠道确认；排除“收到”等占位回复。TTFT 从模型请求发出算起，不包含排队、检索和发送前审核。</dd></div><div><dt>目标配置不等于生产告警</dt><dd>这里的时长与达标比例是演示目标，不是行业标准。修改后只重算本地样本，不建立定时巡检、不发送告警。</dd></div>${data().metrics.map(metric=>`<div><dt>${metric.name}</dt><dd>${metric.note}</dd></div>`).join('')}</dl></section>`;}
  function charts(report){
    const target=targets()[ui.metric];const metric=data().metrics.find(item=>item.id===ui.metric);
    const max=Math.max(target,...report.trend.map(entry=>entry.metrics[ui.metric].p95||0),1);
    const ceiling=Math.ceil(max/1000)*1000;
    const values=report.rows.map(row=>row[ui.metric]).filter(Number.isFinite);
    const edges=[0,1000,2000,5000,10000,Infinity];
    const buckets=edges.slice(0,-1).map((lower,index)=>({lower,upper:edges[index+1],count:values.filter(value=>value>=lower&&value<edges[index+1]).length,label:['<1s','1–2s','2–5s','5–10s','≥10s'][index]}));
    const maxCount=Math.max(...buckets.map(item=>item.count),1);
    return `<div class="perf-charts"><section class="dash-panel">${sectionHead('延迟趋势','同一请求粒度 · 单日按两小时分组（20点组含20–24点）',`<select id="perf-metric" aria-label="图表延迟指标">${[['ttftMs','首 token 延迟'],['endToEndMs','端到端耗时']].map(([key,title])=>`<option value="${key}" ${ui.metric===key?'selected':''}>${title}</option>`).join('')}</select>`)}<div class="perf-legend"><span><i class="perf-median"></i>P50</span><span><i class="perf-tail"></i>P95</span><span>虚线：示例目标 ${elapsed(target)}</span></div><div class="perf-chart"><div class="perf-axis"><span>${elapsed(ceiling)}</span><span>${elapsed(ceiling/2)}</span><span>0</span></div><div class="perf-columns"><div class="perf-target-line" style="bottom:calc(29px + (100% - 59px) * ${target/ceiling})"></div>${report.trend.map(entry=>{const stats=entry.metrics[ui.metric];const text=`${entry.label}，${metric.name}，P50 ${elapsed(stats.p50)}，P95 ${elapsed(stats.p95)}，样本 ${stats.n} 条；点击筛选下方请求`;return `<button class="perf-column ${ui.day===entry.key?'selected':''}" data-action="analytics-perf-day" data-value="${entry.key}" title="${text}" aria-label="${text}" aria-pressed="${ui.day===entry.key}"><span class="perf-column-value">${stats.p95===null?'—':(stats.p95/1000).toFixed(1)}</span><span class="perf-bar-pair"><i class="perf-median" style="height:${(stats.p50||0)/ceiling*100}%"></i><i class="perf-tail" style="height:${(stats.p95||0)/ceiling*100}%"></i></span><span class="perf-column-label">${entry.label}</span></button>`;}).join('')}</div></div><p class="dash-panel-note">柱顶为 P95（秒）。点击日期只筛选下方请求列表；上方指标范围保持不变。</p></section><section class="dash-panel">${sectionHead('延迟分布',`${metric.name} · 已观测 n=${values.length}，区间左闭右开`)}<div class="perf-histogram">${buckets.map((bucket,index)=>`<button data-action="analytics-perf-range" data-value="${index}" aria-pressed="${ui.range===index}" class="${ui.range===index?'selected':''}" aria-label="${bucket.label}，${bucket.count} 条，筛选请求"><span>${bucket.count}</span><span class="perf-histogram-track"><i style="height:${bucket.count/maxCount*100}%"></i></span><small>${bucket.label}</small></button>`).join('')}</div><p class="dash-panel-note">点击区间查看样本。超时不填成 0 ms，也不混入“完整回复”分布。</p></section></div>`;
  }
  function latencyTable(report){return `<section class="dash-panel">${sectionHead('各环节耗时','分位数定位长尾，样本量说明哪些事件确实被观测到',host.badge('单位自动换算'))}<div class="dash-table-scroll perf-scroll"><table class="perf-latency-table"><thead><tr><th>测量环节</th><th>P50</th><th>P95</th><th>P99</th><th>样本量</th><th>统计边界</th></tr></thead><tbody>${data().metrics.map(metric=>{const stats=report.total.metrics[metric.id];const threshold=targets()[metric.id];return `<tr><th scope="row">${metric.name}<small>${metric.short}</small></th><td>${elapsed(stats.p50)}</td><td class="${threshold&&stats.p95>threshold?'perf-warning':''}">${elapsed(stats.p95)}</td><td>${elapsed(stats.p99)}</td><td>${stats.n}${stats.n&&stats.n<100?'<small>尾部分位仅供观察</small>':''}</td><td class="perf-definition-cell">${metric.note}</td></tr>`;}).join('')}</tbody></table></div><p class="dash-panel-note">工具失败 ${report.total.toolFailures} / ${report.total.toolAttempts} 次尝试；发生重试 ${report.total.retried} / ${report.total.toolRequests} 个工具请求。入站时间不包含在端到端内；各环节 P95 不能直接相加。</p></section>`;}
  function servicePanel(report){
    const service=report.service;const target=targets();
    const rows=[
      ['客户首响 SLA',pct(service.slaRate),`${service.met} / ${service.matured} 件`, `客户进线 → 首条实质回复确认。AI ≤ ${elapsed(target.aiFrtMs)}；人工 ≤ ${elapsed(target.humanFrtMs)}。均按自然时间；已过目标仍未回复计未达标。`],
      ['AI 首响 / 人工首响 · P95',`${elapsed(service.aiFrt.p95)} / ${elapsed(service.humanFrt.p95)}`,`AI n=${service.aiFrt.n}；人工 n=${service.humanFrt.n}`,'按首次接待方式分组。含接入、编排、审核与渠道回传，不等于模型 TTFT。'],
      ['人工排队 · P95',elapsed(service.queue.p95),`n=${service.queue.n}`,'进入人工队列 → 坐席接单。与助手调度排队分开统计。'],
      ['平均处理时长 · AHT',elapsed(service.aht.mean),`已结束人工处理 n=${service.aht.n}`,'人工处理忙时 + 后处理时间，排除客户等待和排队；不是模型生成耗时。'],
      ['解决时长 · P95',elapsed(service.resolution.p95),`有解决证据 n=${service.resolution.n}`,'进线 → 确认解决，按自然时间。未解决单列，不用关闭会话代替解决。'],
      ['转人工率',pct(rate(service.transferred,service.aiStarted)),`${service.transferred} / ${service.aiStarted} 件 AI 起始问题`,'曾进入人工队列的问题 / AI 起始问题；直接进入人工的会话不计分母。'],
      ['首次联系解决 · FCR（24h）',pct(rate(service.fcr,service.observed)),`${service.fcr} / ${service.observed} 件成熟问题`,'第一次联系有解决证据，且进线后 24h 未再次联系。仅统计完整观察 24h 的问题。'],
      ['重复咨询率（24h）',pct(rate(service.repeated,service.observed)),`${service.repeated} / ${service.observed} 件成熟问题`,'进线后 24h 内，同一服务问题再次联系。不把跨渠道重复消息算成新问题。'],
      ['重开率（解决后 24h）',pct(rate(service.reopened,service.reopenEligible)),`${service.reopened} / ${service.reopenEligible} 件`,'已确认解决后重新进入处理，分母仅包含解决后已完整观察 24h 的问题。'],
      ['客户满意度 · CSAT',pct(rate(service.satisfied,service.scored)),`${service.satisfied} / ${service.scored} 份有效评价`,'5 分量表中 4–5 分为满意；不回答问卷的客户不算满意，也不能推断答案准确。'],
      ['评价响应率',pct(rate(service.scored,service.invited)),`${service.scored} / ${service.invited} 次邀请`,'展示问卷覆盖偏差。未邀请和已邀请未回答分别保留。']
    ];
    return `<section class="dash-panel perf-service">${sectionHead('客服效率与服务质量',`独立会话样本 · 当前日期 / 渠道共 ${service.count} 件；不受助手 / 模型筛选影响`,host.badge('会话粒度'))}<div class="perf-service-summary"><div><span>客户首响 SLA</span><strong>${pct(service.slaRate)}</strong><small>${service.met} / ${service.matured} 件达标</small></div><div><span>仍未回复</span><strong>${service.unanswered}<small> 件</small></strong><small>保留在 SLA 分母</small></div><div><span>未确认解决</span><strong>${service.count-service.resolution.n}<small> 件</small></strong><small>不混入已解决耗时</small></div><div><span>完整观察 24h</span><strong>${service.observed}<small> 件</small></strong><small>单日新样本可显示 —</small></div></div><details class="perf-service-details" open><summary>查看 ${rows.length} 项客服指标与口径</summary><div class="dash-table-scroll perf-scroll"><table><thead><tr><th>指标</th><th>当前值</th><th>样本 / 分母</th><th>计算口径</th></tr></thead><tbody>${rows.map(([title,value,sample,note])=>`<tr><th scope="row">${title}</th><td><strong>${value}</strong></td><td>${sample}</td><td class="perf-definition-cell">${note}</td></tr>`).join('')}</tbody></table></div></details></section>`;
  }
  function listRows(report){const edges=[0,1000,2000,5000,10000,Infinity];const target=targets()[ui.metric];return report.rows.filter(row=>(!ui.day||(ui.period==='today'?row.hour:row.date)===ui.day)&&(ui.range===null||Number.isFinite(row[ui.metric])&&row[ui.metric]>=edges[ui.range]&&row[ui.metric]<edges[ui.range+1])&&(ui.status==='all'||ui.status==='slow'&&(row[ui.metric]>target||['timeout','error'].includes(row.status))||ui.status===row.status)).sort((left,right)=>right.elapsedMs-left.elapsedMs);}
  function requestList(report){const rows=listRows(report);return `<section class="dash-panel perf-requests" id="perf-request-list">${sectionHead('慢请求与异常记录',`当前列表 ${rows.length} 条 · 与上方样本同源；点击查看阶段时间线`,filter('status','请求状态',[['slow','慢请求 + 超时 / 失败'],['all','全部请求'],['timeout','仅超时'],['error','仅失败'],['running','处理中'],['cancelled','已取消']]))}${ui.day||ui.range!==null?`<div class="perf-list-scope"><span>列表下钻：${escape(ui.day||'全部日期')} · ${ui.range===null?'全部时长':['<1s','1–2s','2–5s','5–10s','≥10s'][ui.range]}</span>${button('清除列表下钻','clear-list','','quiet small')}</div>`:''}<div class="dash-table-scroll perf-scroll"><table><thead><tr><th>请求 / 时间</th><th>助手 / 模型</th><th>状态</th><th>首 token</th><th>端到端 / 已等待</th><th>卡点线索</th><th>操作</th></tr></thead><tbody>${rows.slice(0,ui.limit).map(row=>`<tr><th scope="row">${row.id}<small>${row.date.slice(5)} ${row.time} · ${channelName(row.channel)}</small></th><td>${agentName(row.agent)}<small>${modelName(row.model)}</small></td><td>${host.badge(labels[row.status],tone(row.status))}</td><td>${elapsed(row.ttftMs)}</td><td>${row.endToEndMs===null?'<span class="perf-warning">'+elapsed(row.elapsedMs)+(row.status==='running'?'（至少）':'（终止）')+'</span>':elapsed(row.endToEndMs)}</td><td>${row.failureStage?({tool:'工具查询超时',model:row.status==='cancelled'?'调用方取消':'模型未返回首 token',delivery:'交付确认失败',queue:'仍在调度队列'})[row.failureStage]:row.attempts.length>1?'工具重试':row.ttftMs>targets().ttftMs?'首 token 偏慢':'阶段耗时待核对'}</td><td>${button('查看步骤','detail',`data-id="${row.id}"`,'quiet small')}</td></tr>`).join('')||'<tr><td colspan="7"><div class="dash-empty-copy">当前条件没有请求。可清除下钻条件或选择“全部请求”。</div></td></tr>'}</tbody></table></div>${rows.length>ui.limit?`<div class="perf-list-footer">${button(`再显示 ${Math.min(20,rows.length-ui.limit)} 条`,'more','','quiet small')}<span>已显示 ${ui.limit} / ${rows.length}</span></div>`:''}</section>`;}
  function detail(){
    const row=data().requests.find(item=>item.id===ui.detail);if(!row){ui.detail=null;return '';}
    const largest=row.stages.reduce((found,item)=>item.duration>found.duration?item:found,row.stages[0]);
    return `<section class="perf-detail"><div class="perf-detail-head">${button('← 返回性能大盘','back','','quiet')}<span>${row.id} · 预置模拟请求</span></div><div class="perf-detail-title"><div><h2>${agentName(row.agent)} · ${labels[row.status]}</h2><p>${row.date} ${row.time} · ${channelName(row.channel)} · ${modelName(row.model)} · ${row.version}</p></div>${host.badge(row.status==='success'?'端到端 '+elapsed(row.endToEndMs):'已观测 '+elapsed(row.elapsedMs)+(row.status==='running'?'（等待下限）':''),tone(row.status))}</div><div class="perf-detail-note"><strong>延迟排查线索</strong><p>${row.failureStage?`本样本在“${row.stages.at(-1).name}”${row.status==='running'?'仍未结束':'终止'}。`:`最长阶段是“${largest.name}”，占已观测时长 ${pct(rate(largest.duration,row.elapsedMs))}。`} 请结合工具返回、版本及重试记录核对。这里只展示预置事件、耗时和状态，不包含隐式思考。</p></div><section class="dash-panel">${sectionHead('执行时间线','以平台受理为 0；横向位置按预置样本偏移，条长表示本阶段耗时')}<div class="perf-waterfall"><div class="perf-waterfall-axis"><span>执行阶段</span><span>0 → ${elapsed(row.elapsedMs)}</span><span>耗时 / 状态</span></div>${row.stages.map((stage,index)=>`<div class="perf-waterfall-row"><span><small>${String(index+1).padStart(2,'0')}</small>${stage.name}</span><div class="perf-waterfall-track"><i class="${stage.status}" style="margin-left:${stage.offset/row.elapsedMs*100}%;width:${stage.duration/row.elapsedMs*100}%" title="开始 ${elapsed(stage.offset)}，结束 ${elapsed(stage.offset+stage.duration)}"></i></div><strong>${elapsed(stage.duration)}<small>${labels[stage.status]}</small></strong></div>`).join('')}</div><p class="dash-panel-note">渠道入站另计 ${elapsed(row.ingressMs)}；首 token ${elapsed(row.ttftMs)}；完整生成 ${elapsed(row.modelMs)}。未结束的阶段不计完成耗时。</p></section><section class="perf-attempts"><h3>工具尝试记录</h3>${row.attempts.length?row.attempts.map(attempt=>`<div><span>${attempt.name} · 第 ${attempt.attempt} 次</span><strong>${elapsed(attempt.duration)}</strong>${host.badge(labels[attempt.status],tone(attempt.status))}</div>`).join(''):'<p>此请求无工具调用记录。</p>'}</section><section class="perf-feedback"><div><h3>交给对应助手跟进</h3><p>将本条预置样本导入 ${agentName(row.agent)} 的执行追踪，再由你选择问题步骤、填写归因并确认登记。重复导入复用同一记录；不自动评测或发布。</p></div>${button('导入追踪并登记问题','import',`data-id="${row.id}"`,'primary')}</section></section>`;
  }
  function page(){const report=snapshot();return `<div class="dash-page perf-page"><header class="dash-header"><div><div class="dash-eyebrow"><span></span>性能统计</div><h1>运营大盘</h1><p>查看首响、生成与交付延迟，排查超时和慢请求。</p></div><div class="dash-header-actions">${button('调整目标','targets','','quiet')}${button('导出性能报表','export','','')}</div></header>${navigation()}${ui.detail?detail():`${filters()}${headline(report)}${ui.definitions?definitions():''}${report.total.count?`${charts(report)}${latencyTable(report)}${requestList(report)}`:'<div class="dash-empty"><h2>当前范围没有性能样本</h2><p>历史存档缺少实时事件时间，无法计算延迟。</p></div>'}${servicePanel(report)}<section class="perf-instrumentation"><h2>尚未采集的指标</h2><p>真实 TPS / 并发、每 token 时间 TPOT、Token 用量与成本、坐席占用率、告警通知：<strong>未采集</strong>。计算这些指标需要接入真实模型流式事件、计费账单和坐席排班。</p></section>`}<footer class="dash-footer"><span>PERF-01 · 全部为固定模拟样本，与真实接入及本地任务耗时分开。</span><span>目标仅用于演示 · 无自动告警</span></footer></div>`;}
  function configureTargets(){const values=targets();host.showDialog('设置演示目标','仅重算本地固定样本，不修改生产配置或启用告警。',`<div class="perf-target-fields">${[['ttftMs','首 token P95 目标（秒）'],['endToEndMs','端到端时长目标（秒）'],['aiFrtMs','AI 客户首响目标（秒）'],['humanFrtMs','人工客户首响目标（秒）'],['goal','端到端达标比例目标（%）']].map(([key,title])=>`<div class="field"><label for="perf-target-${key}">${title}</label><input type="number" id="perf-target-${key}" step="${key==='goal'?1:.1}" min="${targetLimits[key][0]/(key==='goal'?1:1000)}" max="${targetLimits[key][1]/(key==='goal'?1:1000)}" value="${values[key]/(key==='goal'?1:1000)}"></div>`).join('')}</div><p class="perf-dialog-note">有效终态在端到端时长目标内成功交付才算达标。超时和失败计未达标；取消、处理中单列。首 token 目标用于高亮 P95 与筛选慢请求。</p><div id="perf-target-error" role="alert" class="inline-error"></div>`,host.footer('保存目标','analytics-perf-save-targets'));}
  function csv(report){const rows=[['连山 · 性能与 SLA 固定模拟报表'],['数据性质','非生产遥测；逐请求预置样本'],['快照',data().snapshotAt],['范围',JSON.stringify({period:report.period,channel:report.channel,agent:report.filters.agent,model:report.filters.model})],['目标',JSON.stringify(report.targets)],['分位数','nearest-rank：ceil(n*p)；阶段样本仅取已有观测，端到端仅成功'],['成功率分母','成功+失败+超时；取消和处理中单列'],[],['指标','P50(ms)','P95(ms)','P99(ms)','n','口径'],...data().metrics.map(metric=>[metric.name,report.total.metrics[metric.id].p50,report.total.metrics[metric.id].p95,report.total.metrics[metric.id].p99,report.total.metrics[metric.id].n,metric.note]),[],['全部请求','有效终态','成功','超时','失败','取消','处理中','端到端目标达标'],[report.total.count,report.total.terminal,report.total.success,report.total.timeout,report.total.errors,report.total.cancelled,report.total.running,report.total.sloMet],[],['客服指标范围','仅日期与渠道；不随助手/模型筛选'],['客户首响达标','已过目标问题','未回复','FCR(24h)','成熟观察问题','重复咨询(24h)','重开','重开观察分母','满意评价','有效评价','邀请'],[report.service.met,report.service.matured,report.service.unanswered,report.service.fcr,report.service.observed,report.service.repeated,report.service.reopened,report.service.reopenEligible,report.service.satisfied,report.service.scored,report.service.invited],[],['会话耗时指标','平均(ms)','P50(ms)','P95(ms)','P99(ms)','n'],...['aiFrt','humanFrt','queue','aht','resolution'].map(key=>[key,report.service[key].mean,report.service[key].p50,report.service[key].p95,report.service[key].p99,report.service[key].n]),['转人工','AI起始问题'],[report.service.transferred,report.service.aiStarted],[],['请求','日期','时段','渠道','助手','模型','状态','TTFT(ms)','完整生成(ms)','端到端(ms)','已观测(ms)'],...report.rows.map(row=>[row.id,row.date,row.time,row.channel,row.agent,row.model,row.status,row.ttftMs,row.modelMs,row.endToEndMs,row.elapsedMs])];return '\ufeff'+rows.map(row=>row.map(value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');}
  function dispatch(name,element){const value=element.dataset.value;const identifier=element.dataset.id;
    if(name==='definitions'){ui.definitions=!ui.definitions;return refresh();}
    if(name==='targets')return configureTargets();
    if(name==='save-targets'){const proposed={};for(const key of Object.keys(data().defaults)){const input=document.getElementById('perf-target-'+key);const number=Number(input.value)*(key==='goal'?1:1000);if(!input.value.trim()||!Number.isFinite(number)||number<targetLimits[key][0]||number>targetLimits[key][1]){document.getElementById('perf-target-error').textContent='请按各输入框的范围填写有效正数。';input.focus();return;}proposed[key]=number;}host.getState().performanceTargets=proposed;host.persist();host.closeDialog();refresh();return host.toast('演示目标已保存，样本已重算；未启用生产告警。');}
    if(name==='day'){if(!snapshot().trend.some(entry=>entry.key===value))return;ui.day=ui.day===value?null:value;ui.limit=12;refresh();return document.getElementById('perf-request-list')?.scrollIntoView({block:'start'});}
    if(name==='range'){const index=Number(value);if(!Number.isInteger(index)||index<0||index>4)return;ui.range=ui.range===index?null:index;ui.status='all';ui.limit=12;refresh();return document.getElementById('perf-request-list')?.scrollIntoView({block:'start'});}
    if(name==='clear-list'){ui.day=null;ui.range=null;ui.limit=12;return refresh();}
    if(name==='more'){ui.limit+=20;return refresh();}
    if(name==='detail'){if(!data().requests.some(row=>row.id===identifier))return;ui.detail=identifier;return refresh(null,true);}
    if(name==='back'){ui.detail=null;return refresh(null,true);}
    if(name==='import'){if(!data().requests.some(row=>row.id===identifier))return;return host.showDialog('导入一条预置性能样本','不会运行真实模型或发出客户消息。',`<p class="perf-dialog-note">${escape(identifier)} 的阶段时间、模型标签、状态和工具尝试将进入对应助手的执行追踪，保留“预置模拟样本”来源。没有客户原文或密钥。</p><label class="check-label"><input id="perf-import-consent" type="checkbox"><span>确认用于演示问题分析，不把样本当作实际运行记录。</span></label>`,host.footer('导入并选择问题步骤','analytics-perf-import-confirm',`data-id="${identifier}"`));}
    if(name==='import-confirm'){if(!document.getElementById('perf-import-consent')?.checked)return host.toast('请先确认样本用途。',true);const traceId=window.TraceHub.importPerformanceSample(identifier);if(traceId){host.closeDialog();window.TraceHub.setScope(data().requests.find(row=>row.id===identifier).agent,'traces');window.TraceHub.dispatch('open',{dataset:{id:traceId}});}return;}
    if(name==='export'){const report=snapshot();if(!report.total.count)return host.toast('当前范围没有可导出的性能样本。',true);exportSnapshot=JSON.parse(JSON.stringify({...report,filters:ui,targets:targets()}));return host.showDialog('导出当前性能范围','仅下载本机模拟样本，不上传。',`<p class="perf-dialog-note">${report.total.count} 个请求，包含 P50 / P95 / P99、分母、目标及逐请求耗时。客服指标独立按日期 / 渠道汇总，不包含客户原文或密钥。</p><label class="check-label"><input id="perf-export-consent" type="checkbox"><span>确认下载固定模拟样本，不作为实际服务成绩。</span></label>`,host.footer('下载 CSV','analytics-perf-export-confirm'));}
    if(name==='export-confirm'){if(!document.getElementById('perf-export-consent')?.checked||!exportSnapshot)return host.toast('请先确认导出范围。',true);const blob=new Blob([csv(exportSnapshot)],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='连山_性能与SLA_固定模拟样本.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exportSnapshot=null;host.closeDialog();return host.toast('已下载当前范围的模拟报表。');}
  }
  function change(identifier,value){const key=identifier.replace('perf-','');const options={period:['week','today'],channel:['all','archive',...window.HubAnalyticsData.channels.map(entry=>entry.id)],agent:['all',...data().agents.map(entry=>entry.id)],model:['all',...data().models.map(entry=>entry.id)],metric:['ttftMs','endToEndMs'],status:['slow','all','timeout','error','running','cancelled']};if(!options[key]?.includes(value))return;ui[key]=value;ui.limit=12;if(key!=='status'){ui.day=null;ui.range=null;}refresh(identifier);}
  return {configure(adapter){host=adapter;},page,dispatch,change,openScope(scope,detail=null){ui={...initial(),period:scope.period==='week'?'week':'today',channel:[...window.HubAnalyticsData.channels.map(item=>item.id),'all'].includes(scope.channel)?scope.channel:'all',detail:data().requests.some(item=>item.id===detail)?detail:null};},snapshot,targets,csv,reset(){ui=initial();exportSnapshot=null;}};
})();
